SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");a:=eval Read(ROOT cat "source" cat IntegerToString(LEVEL)cat "_p5.m");k:=GF(5);PK:=PolynomialRing(k);fields:=AssociativeArray();for r in a[1]do fields[r[1]]:=ext<k|PK!r[2]>;end for;
function Ky(v,d)vs:=[];for j in[1..d]do Append(~vs,&cat[[Integers()!a:a in Eltseq(z,k)]:z in v]);v:=[z^5:z in v];end for;return Sort(vs)[1];end function;
out:=[* *];for d in[3..7]do K:=fields[d];keys:={};n:=0;for si in[1..#a[3]]do r:=a[3][si];if r[1]ne d then continue;end if;ky:=r[2];E:=EllipticCurve([K|1-Evaluate(PK!ky[d+1..2*d],K.1),-Evaluate(PK!ky[1..d],K.1),-Evaluate(PK!ky[1..d],K.1),0,0]);P:=E![0,0];assert LEVEL*P eq E!0 and &and[(LEVEL div ell)*P ne E!0:ell in PrimeDivisors(LEVEL)];for u in[1..LEVEL div 2]do if GCD(u,LEVEL)eq 1 then Include(~keys,Ky(TateNormalForm_bc(E,u*P),d));end if;end for;n+:=1;end for;assert #keys eq a[2][d];Append(~out,[*d,Sort(Setseq(keys))*]);print "D31A_LOW_ACTUAL_SOURCE_DEGREE",LEVEL,d,n,#keys,Cputime(tt);end for;
Write(ROOT cat "low_actual_source.m",Sprint([*a[1],out*]):Overwrite:=true);print "D31A_LOW_ACTUAL_SOURCE_COMPLETE",LEVEL,Cputime(tt);quit;
